import React, { useEffect, useState } from "react";
import axios from "axios";
import Product from "./Product";
import "./ProductList.scss";

const ProductList = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    axios
      .get("/products.json")
      .then((response) => {
        if (Array.isArray(response.data)) {
          setProducts(response.data);
        } else {
          throw new Error("Dados inválidos: esperado um array de produtos");
        }
        setLoading(false);
      })
      .catch((error) => {
        console.error("Erro ao carregar os produtos:", error);
        setError(error.message);
        setLoading(false);
      });
  }, []);

  if (loading) {
    return <div className="loading">Carregando...</div>;
  }

  if (error) {
    return <div className="error">Erro: {error}</div>;
  }

  return (
    <div className="product-page">
    <div className="product-header">
        <h1>Produtos em Destaque</h1>
        <p>Confira nossa seleção especial.</p>
    </div>
    <div className="product-filters">
        <span>FILTRAR POR ▼</span>
        <span>ORDENAR POR ▼</span>
        <span>VISUALIZAR: 4</span>
    </div>
    <div className="product-list">
        {products.map((product) => (
            <div className="product" key={product.productId}>
                <img src={product.imageUrl} alt={product.productName} />
                <h3>{product.productName}</h3>
                <p className="price-vista" id="price-vista">R$ {product.priceVista}</p>
                <p>{product.installments}x de R$ {product.priceParcelado}</p>
                <button className="buy-button" onClick={handleBuy}>QUICK SHOP</button>
            </div>
        ))}
    </div>
</div>
  );
};

export default ProductList;
